1	import { Helpers } from "../helpers";
2	import { SR5Item } from "../item/SR5Item";
3	import { SR5Actor } from "../actor/SR5Actor";
4	import { ModifiableValue } from "../mods/ModifiableValue";
5	import { Migrator } from "../migrator/Migrator";
6	import { LinksHelpers } from '@/module/utils/links';
7	import { ModifiableValueType } from "../types/template/Base";
8	import DataModel = foundry.abstract.DataModel;
9	
10	/**
11	 * Shadowrun Active Effects implement additional ways of altering document data.
12	 *
13	 * The main difference to the base implementation is the ability to modify Value structures without the need to define
14	 * sub-keys. Instead of active effects adding on top of a numerical they'll be included in the mod array of the Value.
15	 *
16	 * Overriding a value is also altered for Values to allow for a more dynamic approach. The original values are still available
17	 * but during calculation the override value will be used instead.
18	 *
19	 * Effects can also define the type of target data to be applied to. Default effects only apply to actor data, system effects
20	 * can apply to actors, tests and also only to actors targeted by tests.
21	 * 
22	 * NOTE: FoundryVTT DataModel is used to apply changes as well. Check custom Field implementations for effect change mode
23	 * application.
24	 */
25	export class SR5ActiveEffect extends ActiveEffect {
26	    /**
27	     * Can be used to determine if the origin of the effect is a document owned by another document.
28	     *
29	     * A use case would be to check if the effect is applied by an actor owned item.
30	     *
31	     * The current approach is a bit simple, due to the limited effect use. Should there be a time of effects applied to
32	     * items, this would need change.
33	     */
34	    public get isOriginOwned(): boolean {
35	        if (!this.origin) return false;
36	        const path = this.origin.split('.');
37	
38	        if (path[0] === 'Scene' && path.length === 6) return true;
39	        if (path[0] === 'Actor' && path.length === 4) return true;
40	
41	        return false;
42	    }
43	
44	    async openSource() {
45	        const source = this.origin;
46	        if (source) {
47	            await LinksHelpers.openSource(source);
48	        }
49	    }
50	
51	    get hasSource(): boolean {
52	        return !!this.origin;
53	    }
54	
55	    public get source() {
56	        return this.origin ? fromUuidSync(this.origin) : null;
57	    }
58	
59	    get isActorOwned(): boolean {
60	        return this.parent instanceof SR5Actor;
61	    }
62	
63	    get isItemOwned(): boolean {
64	        return this.parent instanceof SR5Item;
65	    }
66	
67	    /**
68	     * Always returns the parent actor of the effect, even if the effect is applied to an item.
69	     */
70	    get actor(): SR5Actor | null {
71	        if (this.parent instanceof SR5Actor) return this.parent;
72	        if (this.parent instanceof SR5Item) return this.parent?.parent;
73	        return null;
74	    }
75	
76	    /**
77	     * Use to display this effect on sheet, including a possible parent item structure.
78	     */
79	    public get sheetName(): string | null {
80	        if (this.parent instanceof SR5Actor) return this.name;
81	        return `${this.parent?.name} » ${this.name}`;
82	    }
83	
84	    /**
85	     * Render the sheet of the active effect source
86	     */
87	    public async renderSourceSheet() {
88	        if (this.source instanceof SR5Actor || this.source instanceof SR5Item)
89	            return this.source?.sheet?.render(true);
90	        return undefined;
91	    }
92	
93	    async toggleDisabled() {
94	        return this.update({ disabled: !this.disabled });
95	    }
96	
97	    /**
98	     * Try redirecting given change key to a key matching a ModifiableValue instead of it's leafs.
99	     * Otherwise, redirect key as is. ChangeData will be altered in place.
100	     */
101	    static redirectToNearModifiableValue(model: DataModel.Any, change: ActiveEffect.ChangeData) {
102	        // Move key up one hierarchy and check indirect match
103	        const nodes = change.key.split('.');
104	        const property = nodes.pop() ?? '';
105	        const indirectKey = nodes.join('.');
106	
107	        const value = SR5ActiveEffect.getModifiableValue(model, indirectKey);
108	        if (value) {
109	            // Allow users to change keys that don't affect value calculation
110	            // This could be skill.canDefault or similar.
111	            const keyIsPartOfValueCalculation = this.modifiableValueProperties.includes(property);
112	            if (keyIsPartOfValueCalculation) {
113	                change.key = indirectKey;
114	                return true;
115	            }
116	        }
117	
118	        return false;
119	    }
120	
121	    /**
122	     * Effect change given by user is altered to what is best for the system.
123	     * 
124	     * We do this to avoid effects breaking the sheet and easing the use of custom changes
125	     * for users not aware of system internal around ModifiableValue.
126	     */
127	    static alterChange(model: DataModel.Any, change: ActiveEffect.ChangeData) {
128	        if (!SR5ActiveEffect.getModifiableValue(model, change.key))
129	            SR5ActiveEffect.redirectToNearModifiableValue(model, change);
130	    }
131	
132	    /**
133	     * Return a ModifiableValue at the given key if it matches the ModifiableValue shape.
134	     */
135	    static getModifiableValue(model: DataModel.Any, key: string): ModifiableValueType | null {
136	        const possibleValue = foundry.utils.getProperty(model, key);
137	        const possibleValueType = foundry.utils.getType(possibleValue);
138	
139	        if (possibleValue != null && possibleValueType === 'Object' && Helpers.objectHasKeys(possibleValue, this.modifiableValueProperties))
140	            return possibleValue as ModifiableValueType;
141	
142	        return null;
143	    }
144	
145	    /**
146	     * Return keys expected in the ModifiableField shape
147	     */
148	    static get modifiableValueProperties(): string[] {
149	        return ['base', 'changes', 'value'] satisfies (keyof ModifiableValueType)[];
150	    }
151	
152	    override get isSuppressed(): boolean {
153	        if (!(this.parent instanceof SR5Item)) return false;
154	
155	        if (this.system.onlyForEquipped && !this.parent.isEquipped()) return true;
156	        if (this.system.onlyForWireless && !this.parent.isWireless()) return true;
157	        if (this.parent.isType('critter_power') && !this.parent.system.enabled) return true;
158	        if (this.parent.isType('sprite_power') && !this.parent.system.enabled) return true;
159	
160	        return false;
161	    }
162	
163	    /**
164	     * Determine if this effect is meant to be applied to the actor it's existing on.
165	     *
166	     * Some effects are meant to be applied to other actors, and those shouldn't apply or show
167	     * on the actor that will cause them.
168	     *
169	     * Especially targeted_actor effects are meant to be applied to another actor acted upon but not the one acting.
170	     *
171	     * @return true, when the effect is meant to be applied to the actor it's existing on.
172	     */
173	    get appliesToLocalActor(): boolean {
174	        const actor = this.actor;
175	        if (!actor) return false;
176	
177	        if (this.system.applyTo === 'targeted_actor') {
178	            return this.system.appliedByTest;
179	        }
180	
181	        return true;
182	    }
183	
184	    /**
185	     * Inject features into default FoundryVTT ActiveEffect implementation.
186	     *
187	     * - dynamic source properties as change values
188	     * - apply to non-Actor objects
189	     * 
190	     * With DataModel this method has two different paths it can go:
191	     * - Foundry documents using a DataModel schema
192	     * - Non-Document objects
193	     * 
194	     * The DataModel handles effect application within they applyChange methods.
195	     * The objects are handled by SR5ActiveEffect legacy _applyToObject and _apply methods.
196	     * 
197	     * This can cause diffeing beahvior between these two for effect application.
198	     */
199	    override apply(model: DataModel.Any, change: ActiveEffect.ChangeData) {
200	        // legacyTransferal has item effects created with their items as owner/source.
201	        // modern transferal has item effects directly on owned items.
202	        const source = CONFIG.ActiveEffect.legacyTransferral ? this.source : this.parent;
203	
204	        SR5ActiveEffect.alterChange(model, change);
205	        SR5ActiveEffect.resolveDynamicChangeValue(source, change);
206	
207	        // Add item error case, as FoundryVTT ActiveEffect.apply() is not meant to be used on items.
208	        if (model instanceof SR5Item) throw new Error("SR5ActiveEffect.apply() cannot be used on SR5Item objects.");
209	
210	        // Other cases should be directly applied to the data, without actor / schema handling.
211	        // This is used when applying effects to non-Actor objects, like tests.
212	        if (!(model instanceof SR5Actor)) {
213	            this._applyToObject(model, change);
214	            return {};
215	        }
216	
217	        // Skip applying this change if the target key does not exist on the model.
218	        // TypedObjectField will otherwise create the missing property as a string,
219	        // which breaks data integrity and can result in errors like "undefined[object Object]".
220	        // For example, a change targeting "firstaid" instead of "first_aid" would trigger this case.
221	        if (!foundry.utils.hasProperty(model, change.key))
222	            return {};
223	
224	        return Object.fromEntries(
225	            Object.entries(super.apply(model, change)).filter(([, v]) => v != null)
226	        );
227	    }
228	
229	    /**
230	     * Handle application for none-Document objects
231	     */
232	    private _applyToObject(object: any, change: ActiveEffect.ChangeData) {
233	        const target = foundry.utils.getProperty(object, change.key);
234	        const targetType = foundry.utils.getType(target);
235	
236	        // Cast the effect change value to the correct type
237	        let delta: any;
238	        try {
239	            if (Array.isArray(target)) {
240	                const innerType = target.length ? foundry.utils.getType(target[0]) : "string";
241	                delta = this.__castArray(change.value, innerType);
242	            }
243	            else delta = this.__castDelta(change.value, targetType);
244	        } catch (err) {
245	            console.warn(`Test [${object.constructor.name}] | Unable to parse active effect change for ${change.key}: "${change.value}"`);
246	            return;
247	        }
248	
249	        if (ModifiableValue.isModifiableValue(target)) {
250	            target.changes.push({
251	                enabled: change.effect.active,
252	                invalidated: false,
253	                name: change.effect.name,
254	                value: delta,
255	                mode: change.mode,
256	                priority: change.priority ?? 10 * change.mode,
257	                effectUuid: change.effect.uuid,
258	            });
259	            return undefined;
260	        }
261	
262	        // In case of non-existent change.key targets, catch errors and log it, but still allow the overall process to continue.
263	        // An example could be applying test effect changes, and a single misconfigured effect change shouldn't stop the test dialog 
264	        // from showing up.
265	        try {
266	            return super.apply(object, change);
267	        } catch (err) {
268	            console.error(`Test [${object.constructor.name}] | Failed to apply active effect change for ${change.key}: "${change.value}"`, err);
269	            return undefined;
270	        }
271	    }
272	
273	    /**
274	     * Resolve a dynamic change value to the actual numerical value. A dynamic change value contains key references
275	     * to model properties, which must be resolved before application as literal values.
276	     *
277	     * A dynamic change value follows the same rules as a Foundry roll formula (including dice pools).
278	     *
279	     * A change could contain the key of 'system.attributes.body' with the mode Modify and a dynamic value of
280	     * '@system.technology.rating * 3'. The dynamic property path would be taken from either the source or parent
281	     * document of the effect before the resolved value would be applied onto the target document / object.
282	     *
283	     * @param source Any object style value, either a Foundry document or a plain object
284	     * @param change A singular ActiveEffect.ChangeData object
285	     */
286	    static resolveDynamicChangeValue(source: any, change: ActiveEffect.ChangeData) {
287	        // Dynamic value present?
288	        if (foundry.utils.getType(change.value) !== 'string') return;
289	        if (change.value.length === 0) return;
290	
291	        // Use Foundry Roll Term parser to both resolve dynamic values and resolve calculations.
292	        const expression = Roll.replaceFormulaData(change.value, source);
293	        const value = Roll.validate(expression) ? Roll.safeEval(expression) : change.value;
294	
295	        // Overwrite change value with graceful default, to avoid NaN errors during change application.
296	        // Adhere to FoundryVTT expectation of receiving string values.
297	        if (value === undefined) change.value = '0';
298	        else change.value = value.toString();
299	    }
300	
301	    static override migrateData(data: Parameters<typeof ActiveEffect['migrateData']>[0]) {
302	        Migrator.migrate("ActiveEffect", data);
303	
304	        return super.migrateData(data);
305	    }
306	
307	    override async update(
308	        data: ActiveEffect.UpdateData | undefined,
309	        operation?: ActiveEffect.Database.UpdateOperation,
310	    ) {
311	        if (this.parent instanceof SR5Item && this.parent._isNestedItem) {
312	            if (!data || !this.id) return this;
313	
314	            await this.parent.updateNestedEffects({ ...data, _id: this.id });
315	            await this.render();
316	            return this;
317	        }
318	
319	        await Migrator.updateMigratedDocument(this);
320	
321	        return super.update(data, operation);
322	    }
323	
324	    /**
325	     * This is 1to1 copy from the FoundryVTTv13 method with the private-# prefix...
326	     * Cast a raw ActiveEffect.ChangeData change string to an Array of an inner type.
327	     * @param {string} raw      The raw string value
328	     * @param {string} type     The target data type of inner array elements
329	     * @returns {Array<*>}      The parsed delta cast as a typed array
330	     */
331	    private __castArray(raw: string, type: foundry.utils.DataType) {
332	        let delta: any[];
333	        try {
334	            delta = this.__parseOrString(raw);
335	            delta = delta instanceof Array ? delta : [delta];
336	        } catch (e) {
337	            delta = [raw];
338	        }
339	        return delta.map(d => this.__castDelta(d, type));
340	    }
341	
342	    /**
343	     * This is 1to1 copy from the FoundryVTTv13 method with the private-# prefix...
344	     * Cast a raw ActiveEffect.ChangeData change string to the desired data type.
345	     * @param {string} raw      The raw string value
346	     * @param {string} type     The target data type that the raw value should be cast to match
347	     * @returns {*}             The parsed delta cast to the target data type
348	     */
349	    private __castDelta(raw: string, type: foundry.utils.DataType) {
350	        let delta;
351	        switch (type) {
352	            case "boolean":
353	                delta = Boolean(this.__parseOrString(raw));
354	                break;
355	            case "number":
356	                delta = Number.fromString(raw);
357	                if (Number.isNaN(delta)) delta = 0;
358	                break;
359	            case "string":
360	                delta = String(raw);
361	                break;
362	            default:
363	                delta = this.__parseOrString(raw);
364	        }
365	        return delta;
366	    }
367	
368	    /**
369	     * This is 1to1 copy from the FoundryVTTv13 method with the private-# prefix...
370	     * Parse serialized JSON, or retain the raw string.
371	     * @param {string} raw      A raw serialized string
372	     * @returns {*}             The parsed value, or the original value if parsing failed
373	     */
374	    private __parseOrString(raw: string) {
375	        try {
376	            return JSON.parse(raw);
377	        } catch (err) {
378	            return raw;
379	        }
380	    }
381	}
