1	import { SR5 } from '@/module/config';
2	import { SYSTEM_NAME } from '@/module/constants';
3	import { VersionMigration } from "../VersionMigration";
4	import { DataDefaults } from '@/module/data/DataDefaults';
5	
6	
7	type LegacySkillCategory = 'active' | 'language' | 'knowledge';
8	type LegacyKnowledgeType = 'academic' | 'interests' | 'professional' | 'street';
9	type SkillAttribute = keyof typeof SR5.attributes | '';
10	type SkillLimit = keyof typeof SR5.limits | '';
11	type SkillRequirement = keyof typeof SR5.specialTypes;
12	type LegacySkillData = Record<string, unknown>;
13	type LegacySkillContainer = LegacySkillData | {
14	    attribute?: string;
15	    value?: Record<string, LegacySkillData>;
16	};
17	type NecessaryOwnedSkillItemData = {
18	    type?: string;
19	    name?: string;
20	    system?: {
21	        type?: string;
22	        skill?: {
23	            category?: string;
24	        };
25	    };
26	};
27	type NecessaryActorData = {
28	    type: string
29	    items?: NecessaryOwnedSkillItemData[];
30	    system: {
31	        skills?: {
32	            active?: Record<string, LegacySkillData>;
33	            language?: LegacySkillContainer;
34	            knowledge?: Partial<Record<LegacyKnowledgeType, LegacySkillContainer>> & Record<string, unknown>;
35	        };
36	        skillset: string | undefined
37	    };
38	};
39	
40	type LegacySkillEntry = {
41	    key: string;
42	    skill: LegacySkillData;
43	    category: LegacySkillCategory;
44	    knowledgeType?: LegacyKnowledgeType;
45	    listAttribute?: string;
46	};
47	
48	const LEGACY_KNOWLEDGE_TYPES = ['academic', 'interests', 'professional', 'street'] as const;
49	const LEGACY_KNOWLEDGE_ATTRIBUTES: Record<LegacyKnowledgeType, string> = {
50	    academic: 'logic',
51	    interests: 'intuition',
52	    professional: 'logic',
53	    street: 'intuition',
54	};
