56	/**
57	 * Make sure that readonly fields are set to their correct values.
58	 * Migrate actors from the pre-skill-item storage model where skills only lived in system.skills.
59	 */
60	export class Version0_33_0 extends VersionMigration {
61	    readonly TargetVersion = "0.33.0";
62	
63	    override handlesActiveEffect(_effect: Readonly<any>) {
64	        return _effect.changes.filter(change => change.mode === CONST.ACTIVE_EFFECT_MODES.CUSTOM).length > 0;
65	    }
66	
67	    override migrateActiveEffect(effect: any) {
68	        for (const change of effect.changes)
69	            if (change.mode === CONST.ACTIVE_EFFECT_MODES.CUSTOM)
70	                change.mode = CONST.ACTIVE_EFFECT_MODES.ADD;
71	    }
72	
73	    override handlesItem(item: Readonly<any>): boolean {
74	        if (item.type !== 'weapon') return false;
75	
76	        const rangeTargets = [
77	            item.system?.range?.ranges,
78	            item.system?.thrown?.ranges
79	        ] as const;
80	
81	        return rangeTargets.some(ranges => 
82	            ranges 
83	            && ranges.category !== 'manual' 
84	            && ranges.attribute === 'agility'
85	        );
86	    }
87	
88	    override migrateItem(item: any): void {
89	        const strengthSet = new Set([
90	            "thrownKnife",
91	            "net",
92	            "shuriken",
93	            "standardThrownGrenade",
94	            "aerodynamicThrownGrenade",
95	            "bow"
96	        ] as const);
97	
98	        const rangeTargets = [
99	            item.system?.range?.ranges,
100	            item.system?.thrown?.ranges
101	        ] as const;
102	
103	        for (const ranges of rangeTargets) {
104	            if (!ranges || ranges.category === 'manual') continue;
105	            ranges.attribute = strengthSet.has(ranges.category) ? "strength" : "";
106	        }
107	    }
108	
109	    /**
110	     * Only migrate if an actor actually has skills.
111	     */
112	    override handlesActor(actor: Readonly<unknown>) {
113	        return this.collectLegacySkills(actor as NecessaryActorData).length > 0;
114	    }
115	
116	    override migrateActor(actor: unknown) {
117	        const migratingActor = actor as NecessaryActorData;
118	        const legacySkills = this.collectLegacySkills(migratingActor);
119	
120	        if (legacySkills.length === 0) return;
121	
122	        migratingActor.items ??= [];
123	        const skillSetUuid = this.defaultSkillSet(migratingActor.type);
124	        migratingActor.system.skillset = skillSetUuid;
125	
126	        for (const entry of legacySkills) {
127	            migratingActor.items.push(this.createSkillItem(entry, skillSetUuid) as NecessaryOwnedSkillItemData);
128	        }
129	
130	        if (migratingActor.system) {
131	            migratingActor.system.skills = {};
132	        }
133	
134	    }
135	
136	    /** SKILL ITEM MIGRATION */
137	    private skillPackIcons?: ReadonlyMap<string, string>;
138	
139	    private collectLegacySkills(actor: Readonly<NecessaryActorData>): LegacySkillEntry[] {
140	        const legacySkills: LegacySkillEntry[] = [];
141	        const skills = actor.system?.skills;
142	        if (!skills || typeof skills !== 'object') return legacySkills;
143	        const existingSkills = this.collectOwnedSkillKeys(actor);
144	
145	        legacySkills.push(...this.collectSkillEntries(skills.active, { category: 'active' }, existingSkills));
146	        legacySkills.push(...this.collectSkillEntries(skills.language, { category: 'language' }, existingSkills));
147	
148	        if (skills.knowledge && typeof skills.knowledge === 'object') {
149	            for (const [knowledgeType, knowledgeSkills] of Object.entries(skills.knowledge)) {
150	                if (!this.isLegacyKnowledgeType(knowledgeType)) continue;
151	
152	                legacySkills.push(...this.collectSkillEntries(knowledgeSkills as LegacySkillContainer | undefined, {
153	                    category: 'knowledge',
154	                    knowledgeType,
155	                }, existingSkills));
156	            }
157	        }
158	
159	        return legacySkills;
160	    }
161	
162	    private collectOwnedSkillKeys(actor: Readonly<NecessaryActorData>) {
163	        const keys = new Set<string>();
164	
165	        for (const item of actor.items ?? []) {
166	            if (item?.type !== 'skill') continue;
167	            if (item.system?.type !== 'skill') continue;
168	
169	            const name = this.readString(item.name);
170	            const category = this.readString(item.system?.skill?.category) as LegacySkillCategory | '';
171	            if (!name || !category) continue;
172	
173	            keys.add(this.buildSkillKey(name, category));
174	        }
175	
176	        return keys;
177	    }
178	
179	    private collectSkillEntries(
180	        skillContainer: LegacySkillContainer | undefined,
181	        meta: { category: LegacySkillCategory; knowledgeType?: LegacyKnowledgeType },
182	        existingSkills: Set<string>,
183	    ): LegacySkillEntry[] {
184	        if (!skillContainer || typeof skillContainer !== 'object') return [];
185	
186	        const entries: Record<string, unknown> =
187	            'value' in skillContainer && skillContainer.value && typeof skillContainer.value === 'object'
188	                ? skillContainer.value as Record<string, unknown>
189	            : skillContainer as Record<string, unknown>;
190	        const listAttribute = typeof skillContainer.attribute === 'string' ? skillContainer.attribute : '';
191	
192	        return Object.entries(entries).flatMap(([key, skill]) => {
193	            if (!this.isLegacySkillField(skill)) return [];
194	
195	            const entry = {
196	                key,
197	                skill,
198	                category: meta.category,
199	                knowledgeType: meta.knowledgeType,
200	                listAttribute,
201	            };
202	            const skillName = this.getSkillName(entry);
203	            if (!skillName) return [];
204	
205	            const skillKey = this.buildSkillKey(skillName, meta.category);
206	            if (existingSkills.has(skillKey)) return [];
207	
208	            return [entry];
209	        });
210	    }
211	
212	    private isLegacySkillField(skill: unknown): skill is Record<string, unknown> {
213	        if (!skill || typeof skill !== 'object') return false;
214	
215	        return ['attribute', 'base', 'canDefault', 'description', 'group', 'id', 'img', 'isNative', 'limit', 'link', 'name', 'requirement', 'specs', 'value']
216	            .some(key => key in skill);
217	    }
218	
219	    private isLegacyKnowledgeType(value: string): value is LegacyKnowledgeType {
220	        return (LEGACY_KNOWLEDGE_TYPES as readonly string[]).includes(value);
221	    }
222	
223	    private createSkillItem(entry: LegacySkillEntry, skillSetUuid: string|undefined): Item.CreateData {
224	        const name = this.getSkillName(entry);
225	        if (!name) {
226	            throw new Error(`Shadowrun5e | Failed to migrate legacy ${entry.category} skill due to missing name`);
227	        }
228	
229	        return {
230	            _id: foundry.utils.randomID(16),
231	            name,
232	            type: 'skill',
233	            img: this.getSkillImage(name, entry.skill),
234	            system: DataDefaults.baseSystemData('skill', {
235	                type: 'skill',
236	                description: {
237	                    value: this.readString(entry.skill.description),
238	                    source: this.readString(entry.skill.link),
239	                },
240	                skill: {
241	                    category: entry.category,
242	                    knowledgeType: entry.knowledgeType ?? 'academic',
243	                    attribute: this.getSkillAttribute(entry),
244	                    defaulting: this.getSkillDefaulting(entry),
245	                    rating: this.getSkillRating(entry.skill),
246	                    limit: {
247	                        attribute: this.getSkillLimit(entry.skill.limit),
248	                    },
249	                    specializations: this.getSpecializations(entry.skill.specs),
250	                    requirement: this.getSkillRequirement(entry.skill.requirement),
251	                    language: {
252	                        isNative: Boolean(entry.skill.isNative),
253	                    },
254	                },
255	                source: {
256	                    uuid: skillSetUuid,
257	                }
258	            }),
259	            effects: [],
260	        } as Item.CreateData;
261	    }
262	
263	    private getSkillName(entry: LegacySkillEntry) {
264	        const explicitName = this.readString(entry.skill.name);
265	        if (explicitName) return explicitName;
266	
267	        if (entry.category !== 'active') return '';
268	
269	        return this.readString(entry.key)
270	            .split(/[_\-\s]+/)
271	            .filter(Boolean)
272	            .map(word => word.charAt(0).toUpperCase() + word.slice(1))
273	            .join(' ');
274	    }
275	
276	    private getSkillAttribute(entry: LegacySkillEntry): SkillAttribute {
277	        const attribute = this.readString(entry.skill.attribute);
278	        if (attribute && this.isSkillAttribute(attribute)) return attribute;
279	        if (entry.listAttribute && this.isSkillAttribute(entry.listAttribute)) return entry.listAttribute;
280	
281	        const knowledgeAttribute = entry.category === 'knowledge' && entry.knowledgeType
282	            ? LEGACY_KNOWLEDGE_ATTRIBUTES[entry.knowledgeType]
283	            : '';
284	        if (knowledgeAttribute && this.isSkillAttribute(knowledgeAttribute)) return knowledgeAttribute;
285	
286	        return '';
287	    }
288	
289	    private getSkillDefaulting(entry: LegacySkillEntry) {
290	        if (entry.category !== 'active') return false;
291	
292	        return Boolean(entry.skill.canDefault);
293	    }
294	
295	    private getSkillRating(skill: LegacySkillData) {
296	        const base = this.readNumber(skill.base);
297	        const value = this.readNumber(skill.value);
298	
299	        if (Boolean(skill.isNative) && value > 0) return value;
300	        if (Number.isFinite(base)) return base;
301	        if (Number.isFinite(value)) return value;
302	
303	        return 0;
304	    }
305	
306	    private getSpecializations(specs: unknown) {
307	        if (!Array.isArray(specs)) return [];
308	
309	        return specs
310	            .map(spec => this.readString(spec))
311	            .filter(Boolean)
312	            .map(name => ({ name }));
313	    }
314	
315	    private getSkillLimit(limit: unknown): SkillLimit {
316	        const value = this.readString(limit);
317	        return this.isSkillLimit(value) ? value : '';
318	    }
319	
320	    private getSkillRequirement(requirement: unknown): SkillRequirement {
321	        const value = this.readString(requirement);
322	        return this.isSkillRequirement(value) ? value : 'mundane';
323	    }
324	
325	    private getSkillImage(name: string, skill: LegacySkillData) {
326	        const packIcon = this.getSkillPackIcons().get(this.readString(name));
327	        return packIcon || this.readString(skill.img) || 'icons/svg/item-bag.svg';
328	    }
329	
330	    private getSkillPackIcons(): ReadonlyMap<string, string> {
331	        if (this.skillPackIcons) return this.skillPackIcons;
332	
333	        const packName = SR5.packNames.SkillsPack;
334	        const pack = game.packs.find(pack => pack.metadata.system === SYSTEM_NAME && pack.metadata.name === packName) as foundry.documents.collections.CompendiumCollection<'Item'> | undefined;
335	        if (!pack) {
336	            this.skillPackIcons = new Map();
337	            return this.skillPackIcons;
338	        }
339	
340	        this.skillPackIcons = new Map(
341	            pack.index
342	                .filter(data => data.type === 'skill')
343	                .flatMap(data => {
344	                    const name = this.readString(data.name);
345	                    const img = this.readString(data.img);
346	                    if (!name || !img) return [];
347	                    return [[name, img] as const];
348	                })
349	        );
350	
351	        return this.skillPackIcons;
352	    }
353	
354	    private buildSkillKey(name: string, category: LegacySkillCategory) {
355	        return `${name.trim().toLowerCase()}:${category}`;
356	    }
357	
358	    private isSkillAttribute(value: string | undefined): value is SkillAttribute {
359	        return value === '' || (!!value && value in SR5.attributes);
