4	/**
5	 * Base class for version migrations that convert game data from an older version to a newer one.
6	 * 
7	 * By default, only actors, items, and active effects are handled, but subclasses may extend
8	 * this class to support additional data types as needed.
9	 * 
10	 * These methods are designed to be atomic and modular, enabling precise upgrades
11	 * without requiring full system-wide context.
12	 * 
13	 * Note: if you want to sanitize a document without migration, return true on the handles functions,
14	 * and not implement a migration function for the document. Sanitation then will be called.
15	 * 
16	 * Note: if you want to migrate a new embedded item during document migration, consider this approach:
17	 *
18	 * override migrateActor(_actor: any): void {
19	 *     _actor.items.push({
20	 *         name: "New Embedded Item",
21	 *         type: "action",
22	 *         _id: foundry.utils.randomID(16),
23	 *         system: DataDefaults.baseSystemData('action'),
24	 *     } as any);
25	 * }
26	 */
27	export abstract class VersionMigration {
28	    abstract TargetVersion: `${number}.${number}.${number}`;
29	
30	    migrateActor(_actor: any): void {}
31	    handlesActor(_actor: Readonly<any>) { return this.migrates.Actor; }
32	
33	    migrateItem(_item: any): void {}
34	    handlesItem(_item: Readonly<any>) { return this.migrates.Item; }
35	
36	    migrateActiveEffect(_effect: any): void {}
37	    handlesActiveEffect(_effect: Readonly<any>) { return this.migrates.ActiveEffect; }
38	
39	    /**
40	     * Flags which migration methods have been overridden in the subclass.
41	     * Used to determine support for each document type.
42	     */
43	    private readonly migrates: Record<MigratableDocumentName, boolean>;
44	    constructor() {
45	        const proto = Object.getPrototypeOf(this);
46	        this.migrates = {
47	            Actor: proto.migrateActor !== VersionMigration.prototype.migrateActor,
48	            Item: proto.migrateItem !== VersionMigration.prototype.migrateItem,
49	            ActiveEffect: proto.migrateActiveEffect !== VersionMigration.prototype.migrateActiveEffect
50	        };
51	    }
52	}
