1	import { FLAGS } from "../constants";
2	import { Sanitizer } from "../sanitizer/Sanitizer";
3	import { Version0_8_0 } from "./versions/Version0_8_0";
4	import { Version0_18_0 } from './versions/Version0_18_0';
5	import { Version0_16_0 } from './versions/Version0_16_0';
6	import { Version0_27_0 } from './versions/Version0_27_0';
7	import { Version0_30_0 } from './versions/Version0_30_0';
8	import { Version0_30_3 } from './versions/Version0_30_3';
9	import { Version0_30_6 } from './versions/Version0_30_6';
10	import { Version0_31_0 } from './versions/Version0_31_0';
11	import { Version0_31_5 } from './versions/Version0_31_5';
12	import { Version0_32_0 } from './versions/Version0_32_0';
13	import { Version0_32_1 } from './versions/Version0_32_1';
14	import { Version0_32_4 } from './versions/Version0_32_4';
15	import { Version0_33_0 } from './versions/Version0_33_0';
16	import { VersionMigration, MigratableDocument, MigratableDocumentName } from "./VersionMigration";
17	const { deepClone } = foundry.utils;
18	
19	/**
20	 * Seamless data migrator for the SR5 system.
21	 * 
22	 * This will automatically migrate data during world load and persist the changes on a otherwise
23	 * unconnected document update.
24	 * 
25	 * Using this approach allows the system to both load collection, compendium and imported document data,
26	 * apply migrations for missing migration steps, based on the documents last system schema version.
27	 *
28	 * The migration is done during world load, to avoid documents entering the "invalid document" state
29	 * and allow users a seamless experience when opening an out-of-date world / document.
30	 * 
31	 * Documents will get remigrated so long until the migrated data can be applied on the next update made to
32	 * it. If a document is not updated, it will remain out-of-date and be remigrated on every world load.
33	 * 
34	 * For this, check these methods:
35	 * - migrate
36	 * - updateMigratedDocument
37	 */
38	export class Migrator {
39	    // List of all migrators.
40	    // ⚠️ Keep this list sorted in ascending order by version number (oldest → newest).
41	    private static readonly s_Versions = [
42	        new Version0_8_0(),
43	        new Version0_18_0(),
44	        new Version0_16_0(),
45	        new Version0_27_0(),
46	        new Version0_30_0(),
47	        new Version0_30_3(),
48	        new Version0_30_6(),
49	        new Version0_31_0(),
50	        new Version0_31_5(),
51	        new Version0_32_0(),
52	        new Version0_32_1(),
53	        new Version0_32_4(),
54	        new Version0_33_0(),
55	    ] as const;
56	
57	    private static documentsToBeMigrated = 0;
58	
59	    // Generate the migration version mark used to track current system version in documents.
60	    private static get _migrationMark() {
61	        return game.system.version + ".0";
62	    }
63	
64	    // Returns an array of migration functions applicable to the given document type and version.
65	    private static getMigrators(
66	        version: string | null,
67	        type?: MigratableDocumentName,
68	        data?: any
69	    ): readonly VersionMigration[] {
70	        return this.s_Versions.filter(migrator =>
71	            (!type || migrator[`handles${type}`](data)) &&
72	            this.compareVersion(migrator.TargetVersion, version) > 0
73	        );
74	    }
75	
76	    private static normalizeArray(data: any): any[] {
77	        if (data == null) return [];
78	        return Array.isArray(data) ? data : Object.values(data); 
79	    }
80	
81	    private static formatElapsedTime(milliseconds: number): string {
82	        const totalSeconds = Math.round(milliseconds / 1000);
83	        if (totalSeconds < 60) {
84	            return this.formatElapsedUnit(totalSeconds, 'second');
85	        }
86	
87	        const wholeMinutes = Math.floor(totalSeconds / 60);
88	        const remainingSeconds = totalSeconds % 60;
89	        if (wholeMinutes < 60) {
90	            return `${this.formatElapsedUnit(wholeMinutes, 'minute')} ${this.formatElapsedUnit(remainingSeconds, 'second')}`;
91	        }
92	
93	        const wholeHours = Math.floor(wholeMinutes / 60);
94	        const remainingMinutes = wholeMinutes % 60;
95	        return `${this.formatElapsedUnit(wholeHours, 'hour')} ${this.formatElapsedUnit(remainingMinutes, 'minute')}`;
96	    }
97	
98	    private static formatElapsedUnit(value: number, unit: 'second' | 'minute' | 'hour'): string {
99	        const roundedValue = value >= 10 ? Math.round(value) : Math.round(value * 10) / 10;
100	        const label = roundedValue === 1 ? unit : `${unit}s`;
101	        return `${roundedValue} ${label}`;
102	    }
103	
104	    /**
105	     * Applies migration logic to a provided data object of the specified type during world load
106	     * 
107	     * This is connected to Migrator.updateMigratedDocument which will persist migrated data during the
108	     * update process.
109	     * 
110	     * Note: This method was previously called during `_initializeSource`,
111	     * but that caused migration of embedded items to be skipped in synthetic documents.
112	     */
113	    public static migrate(type: MigratableDocumentName, data: any, nested = false, path: string[] = []): boolean {
114	        // Nested Items and AEs before V10 doesn't have _stats and also is not automatically added when loaded from server.
115	        if (nested || (type === "ActiveEffect" && data.label)) {
116	            data.type ??= "base";
117	            data._stats ??= {};
118	            data._stats.systemVersion ??= "0.0.0";
119	        }
120	
121	        // If _stats is missing, or systemVersion is not present, or the document is already migrated, skip migration.
122	        if (!data._stats || !('systemVersion' in data._stats)) return false;
123	        if (this.compareVersion(data._stats.systemVersion, game.system.version) === 0) return false;
124	
125	        path = [...path, type, data._id];
126	
127	        let migrated = false;
128	        if (type === "Item") {
129	            const items = this.normalizeArray(data.flags?.shadowrun5e?.embeddedItems);
130	            for (const nestedItems of items) {
131	                const nestedMigrated = this.migrate("Item", nestedItems, true, path);
132	                migrated = migrated || nestedMigrated;
133	            }
134	            foundry.utils.setProperty(data, 'flags.shadowrun5e.embeddedItems', items);
135	
136	            if (nested) {
137	                const effects = this.normalizeArray(data.effects);
138	                for (const nestedEffect of effects) {
139	                    const nestedMigrated = this.migrate("ActiveEffect", nestedEffect, true, path);
140	                    migrated = migrated || nestedMigrated;
141	                }
142	                foundry.utils.setProperty(data, 'effects', effects);
143	            }
144	        }
145	
146	        const migrators = this.getMigrators(data._stats.systemVersion, type, data);
147	
148	        if (migrators.length === 0) {
149	            if (migrated)
150	                data._stats.systemVersion = nested ? game.system.version : this._migrationMark;
151	
152	            return migrated;
153	        }
154	
155	        for (const migrator of migrators)
156	            migrator[`migrate${type}`](data);
157	
158	        // After all migrations, sanitize the data model.
159	        // This ensures that the data conforms to the current schema.
160	        const schema = CONFIG[type].dataModels[data.type].schema;
161	        const correctionLogs = Sanitizer.sanitize(schema, data.system);
162	
163	        if (correctionLogs) {
164	            console.warn(
165	                `Document Sanitized on Migration:\n` +
166	                `UUID: ${path.join('.')}; Name: ${data.name};\n` +
167	                `Type: ${type}; SubType: ${data.type}; Version: ${data._stats.systemVersion};\n`
168	            );
169	            console.table(correctionLogs);
170	        }
171	
172	        // Mark as a migratable document.
173	        data._stats.systemVersion = nested ? game.system.version : this._migrationMark;
174	        this.documentsToBeMigrated++;
175	        return true;
176	    }
177	
178	    /**
179	     * Apply migrated data to the document to persist and mark it as up-to-date.
180	     * 
181	     * This is connected to Migrator.migrate which will migrate document data on the fly
182	     * during a document migrateData call before data preparation.
183	     * 
184	     * To avoid endless migrations during world load, we assume the document is migrated and will
185	     * persist that migration based on an out of date document system version, whenever it's
186	     * updated next by the user.
187	     * 
188	     * @param doc Updated document.
189	     */
190	    static async updateMigratedDocument(doc: MigratableDocument) {
191	        // No need to migrate if the document is not a migratable document.
192	        if (doc._stats.systemVersion !== this._migrationMark) return;
193	
194	        // Mark document as up-to-date
195	        doc._stats.systemVersion = game.system.version;
196	        doc._source._stats.systemVersion = game.system.version;
197	
198	        // Update Parent First
199	        if (doc.parent instanceof Actor || doc.parent instanceof Item)
200	            await this.updateMigratedDocument(doc.parent);
201	
202	        // Persist the change without triggering diff logic
203	        return doc.update(doc.toObject() as any, { diff: false, recursive: false });
204	    }
205	
206	    public static async BeginMigration() {
207	        if (this.documentsToBeMigrated === 0) return;
208	
209	        const localizedWarningTitle = game.i18n.localize('SR5.MIGRATION.WarningTitle');
210	        const localizedWarningHeader = game.i18n.localize('SR5.MIGRATION.WarningHeader');
211	        const localizedWarningRequired = game.i18n.localize('SR5.MIGRATION.WarningRequired');
212	        const localizedWarningDescription = game.i18n.localize('SR5.MIGRATION.WarningDescription');
213	        const localizedWarningBackup = game.i18n.localize('SR5.MIGRATION.WarningBackup');
214	        const localizedWarningBegin = game.i18n.localize('SR5.MIGRATION.BeginMigration');
215	
216	        const d = new Dialog({
217	            title: localizedWarningTitle,
218	            content:
219	                `<h2 style="color: red; text-align: center">${localizedWarningHeader} (${this.documentsToBeMigrated})</h2>` +
220	                `<p style="text-align: center"><i>${localizedWarningRequired}</i></p>` +
221	                `<p>${localizedWarningDescription}</p>` +
222	                `<h3 style="color: red">${localizedWarningBackup}</h3>`,
223	            buttons: {
224	                ok: {
225	                    label: localizedWarningBegin,
226	                    callback: async () => this.updateAllMigratableDocuments(),
227	                },
228	            },
229	            default: 'ok',
230	        });
231	        d.render(true);
232	    }
233	
234	    // Track migration progress
235	    private static totalMigrations = 0;
236	    private static completedMigrations = 0;
237	    private static progressbar: Notifications.Notification | null = null;
238	    private static updateProgressbar() {
239	        if (!this.progressbar)
240	            this.progressbar = ui.notifications.info("Migrating Documents...", { progress: true });
241	
242	        this.completedMigrations++;
243	        this.progressbar.update({
244	            pct: this.completedMigrations / this.totalMigrations,
245	            message: `Migrating Documents... (${this.completedMigrations}/${this.totalMigrations})`
246	        });
247	    }
248	
249	    /**
250	     * Update documents of a specific type.
251	     */
252	    private static async updateDocuments<Doc extends typeof Actor | typeof Item | typeof ActiveEffect>(
253	        cls: Doc,
254	        docs: NonNullable<Parameters<Doc['implementation']['updateDocuments']>[0]>,
255	        parent: NonNullable<Parameters<Doc['implementation']['updateDocuments']>[1]>['parent'] = null
256	    ) {
257	        this.updateProgressbar();
258	        return cls.implementation.updateDocuments(
259	            docs.filter(d => d._stats?.systemVersion === this._migrationMark) as any,
260	            { diff: false, recursive: false, parent: parent as any }
261	        );
262	    }
263	
264	    /**
265	     * Migrate all actors in the game.
266	     */
267	    private static async updateAllMigratableDocuments() {
268	        const start = performance.now();
269	
270	        // Estimate total migration steps
271	        this.totalMigrations =
272	            1 + game.items.size +                         // Items + their effects
273	            1 + game.actors.size * 2 +                    // Actor + their items + their effects
274	            [...game.actors].reduce((sum, actor) => sum + actor.items.size, 0) +  // Actor item effects
275	            game.scenes.size;                             // Non-actor tokens
276	
277	        /* Items and its embedded Effects */
278	        await this.updateDocuments(Item, deepClone(game.items._source));
279	
280	        for (const item of game.items)
281	            await this.updateDocuments(ActiveEffect, item.toObject().effects, item);
282	
283	        /* Actors and its embedded documents */
284	        await this.updateDocuments(Actor, deepClone(game.actors._source));
285	
286	        for (const actor of game.actors) {
287	            await this.updateDocuments(Item, actor.toObject().items, actor);
288	            await this.updateDocuments(ActiveEffect, actor.toObject().effects, actor);
289	
290	            for (const item of actor.items)
291	                await this.updateDocuments(ActiveEffect, item.toObject().effects, item);
292	        }
293	
294	        /* Tokens */
295	        for (const scene of game.scenes) {
296	            this.updateProgressbar();
297	            await TokenDocument.implementation.updateDocuments(
298	                scene.tokens.map(t => t.toObject()),
299	                { diff: false, recursive: false, parent: scene }
300	            );
301	        }
302	
303	        /* Finalize Migration */
304	        await game.settings.set(game.system.id, FLAGS.KEY_DATA_VERSION, game.system.version);
305	
306	        new Dialog({
307	            title: "Migration Complete",
