3	/**
4	  * Migration: Update spirit actor to use 'system.attributes.force' with 'base' and 'hidden' properties.
5	  * Moves 'system.force' to 'system.attributes.force.base' and sets 'system.attributes.force.hidden' to false.
6	  * Also updates active effect keys from 'system.force' to 'system.attributes.force'.
7	  */
8	export class Version0_31_5 extends VersionMigration {
9	    readonly TargetVersion = "0.31.5";
10	
11	    override handlesActor(_actor: Readonly<any>) {
12	        return _actor.type === 'spirit';
13	    }
14	
15	    override migrateActor(_actor: any) {
16	        const force = _actor.system.attributes?.force;
17	
18	        if (_actor.type === 'spirit' && force) {
19	            force.base = _actor.system.force || 0;
20	            force.hidden = false;
21	
22	            delete _actor.system.force;
23	        }
24	    }
