import { VersionMigration } from "../VersionMigration";

/**
 * Migration for version 0.33.1:
 * - Migrates the legacy active effect apply-to value 'test' to 'test_all'.
 *
 *   The single 'test' apply-to target was split into 'test_all' and 'test_item'. Effects created before
 *   that split still store the removed 'test' value, which no longer matches any apply-to filter. As a
 *   result they are silently skipped when applying to tests (and later reset to the 'actor' default by the
 *   schema sanitizer), so their bonus quietly stops working with no error or warning.
 *
 *   The 'test' → 'test_all' mapping restores the original "applies to every test" behavior, which is what
 *   these effects were configured for before the split.
 *
 *   NOTE: The apply-to value may live in either `system.applyTo` (post 0.30.0) or, for effects that never
 *   ran the 0.30.0 migration yet, the legacy `flags.shadowrun5e.applyTo`. Both storage locations are
 *   handled so the fix applies wherever the old data happens to be stored. Version0_30_0 moves the flag
 *   onto `system` before this migration runs, so converting `system.applyTo` is enough in practice, but
 *   the flag is converted defensively as well.
 */
export class Version0_33_1 extends VersionMigration {
    readonly TargetVersion = "0.33.1";

    private static readonly LEGACY_APPLY_TO = 'test';
    private static readonly NEW_APPLY_TO = 'test_all';

    override handlesActiveEffect(effect: Readonly<any>): boolean {
        return effect?.system?.applyTo === Version0_33_1.LEGACY_APPLY_TO
            || effect?.flags?.shadowrun5e?.applyTo === Version0_33_1.LEGACY_APPLY_TO;
    }

    override migrateActiveEffect(effect: any): void {
        if (effect?.system?.applyTo === Version0_33_1.LEGACY_APPLY_TO) {
            effect.system.applyTo = Version0_33_1.NEW_APPLY_TO;
        }

        if (effect?.flags?.shadowrun5e?.applyTo === Version0_33_1.LEGACY_APPLY_TO) {
            effect.flags.shadowrun5e.applyTo = Version0_33_1.NEW_APPLY_TO;
        }
    }
}

