    describe('Version0_33_1 legacy apply-to migration', () => {
        const createLegacyEffect = (system: Record<string, unknown>, extra: Record<string, unknown> = {}) => ({
            _id: foundry.utils.randomID(16),
            _stats: { systemVersion: '0.33.0' },
            name: 'Legacy Test Effect',
            type: 'base',
            changes: [{ key: 'data.pool', value: '2', mode: CONST.ACTIVE_EFFECT_MODES.ADD }],
            system,
            ...extra,
        });

        it("migrates the removed 'test' apply-to value to 'test_all'", () => {
            const source = createLegacyEffect({ applyTo: 'test' });

            const migrated = Migrator.migrate('ActiveEffect', source);

            assert.isTrue(migrated);
            assert.strictEqual(foundry.utils.getProperty(source, 'system.applyTo'), 'test_all');
        });

        it("migrates a legacy 'test' apply-to stored on the flag", () => {
            const source = createLegacyEffect(
                {},
                { flags: { shadowrun5e: { applyTo: 'test' } } }
            );

            const migrated = Migrator.migrate('ActiveEffect', source);

            assert.isTrue(migrated);
            assert.strictEqual(foundry.utils.getProperty(source, 'flags.shadowrun5e.applyTo'), 'test_all');
        });

        it('leaves other apply-to values untouched', () => {
            for (const applyTo of ['actor', 'targeted_actor', 'test_all', 'test_item', 'modifier']) {
                const source = createLegacyEffect({ applyTo });

                Migrator.migrate('ActiveEffect', source);

                assert.strictEqual(foundry.utils.getProperty(source, 'system.applyTo'), applyTo);
            }
        });

        it('preserves the rest of the effect configuration', () => {
            const source = createLegacyEffect({
                applyTo: 'test',
                selection_tests: [{ value: 'Success Test', id: 'SuccessTest' }],
            });

            Migrator.migrate('ActiveEffect', source);

            assert.strictEqual(foundry.utils.getProperty(source, 'system.applyTo'), 'test_all');
            assert.deepEqual(
                foundry.utils.getProperty(source, 'system.selection_tests'),
                [{ value: 'Success Test', id: 'SuccessTest' }]
            );
            assert.deepEqual(source.changes, [{ key: 'data.pool', value: '2', mode: CONST.ACTIVE_EFFECT_MODES.ADD }]);
        });
    });

};

